def validate_delimiters(length, program):
    stack = []
    pos_stack = []
    matching = {')': '(', ']': '[', '}': '{'}

    for i in range(length):
        char = program[i]
        if char in "([{":
            stack.append(char)
            pos_stack.append(i)
        elif char in ")]}":
            if not stack or stack[-1] != matching[char]:
                return f"{char} {i}"
            stack.pop()
            pos_stack.pop()

    if stack:
        return f"{stack[-1]} {pos_stack[-1]}"
    else:
        return "ok so far"

